extension Ws.Peer.Mirror {
    /// The mirror applied everything through (term, seq) and its digest there is `digest`. The core compares it with
    /// its own: equal, the acknowledgement is recorded (retention may pass it, the baseline is dropped); different, the
    /// vault stops as diverged on both servers.
    public enum Ack: WsRequest {
