                case term
                case seq
                case digest
                case entries
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            /// The core can say its digest at that position.
            public var known: Bool
            public var match: Bool
            public var recorded: Bool
            /// Always sent; nil is null.
            public var coreDigest: String?
            /// Always sent; nil is null.
            public var coreEntries: Int64?

            public init(known: Bool, match: Bool, recorded: Bool, coreDigest: String? = nil,
                        coreEntries: Int64? = nil) {
                self.known = known
                self.match = match
                self.recorded = recorded
                self.coreDigest = coreDigest
                self.coreEntries = coreEntries
            }

            enum CodingKeys: String, CodingKey {
                case known
                case match
                case recorded
                case coreDigest = "core_digest"
                case coreEntries = "core_entries"
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.known = try container.decode(Bool.self, forKey: .known)
                self.match = try container.decode(Bool.self, forKey: .match)
                self.recorded = try container.decode(Bool.self, forKey: .recorded)
                self.coreDigest = try container.decode(String?.self, forKey: .coreDigest)
                self.coreEntries = try container.decode(Int64?.self, forKey: .coreEntries)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.known, forKey: .known)
                try container.encode(self.match, forKey: .match)
                try container.encode(self.recorded, forKey: .recorded)
