extension Ws.Peer {
    /// The sender unlinked the receiver: the receiver revokes its row too and the connection ends after the answer. A
    /// courtesy: a revoked key is refused at the handshake anyway.
    public enum Unlinked: WsRequest {
        public static let command = WsCommand.peerUnlinked
        /// The daemon reads nothing; the payload is sent as null.
        public typealias Payload = WsNoPayload

        public struct Response: Codable, Hashable, Sendable {
            public var revoked: Bool

            public init(revoked: Bool) {
                self.revoked = revoked
            }

            enum CodingKeys: String, CodingKey {
                case revoked
            }
        }
    }
}
